            <path d="M29.6574 43.6401C32.4307 48.4372 38.5677 50.0778 43.3648 47.3045C48.1619 44.5312 49.8024 38.3942 47.0291 33.5971C44.2558 28.8 38.1188 27.1595 33.3218 29.9328C28.5247 32.7061 26.8841 38.8431 29.6574 43.6401Z" fill="#8B5CF6"/>
